<script setup lang="ts">
import {computed} from 'vue'
import type {Study,FieldDefinition} from '../types'
import {renderLegacy,resolveValue} from '../legacy'
import catalogData from '../catalog.json'
import {date} from '../format'
import {formFields} from '../formSnapshots'
const props=defineProps<{study:Study}>()
const fields=computed(()=>formFields(props.study.fields,props.study.formSnapshot))
const rendered=computed(()=>renderLegacy(props.study.formSnapshot?.code||props.study.templateCode||'',props.study.formSnapshot?.version||props.study.legacy_version||'1',fields.value))
const parameters=computed(()=>{const definitions=props.study.formSnapshot?.definitions||(catalogData as Record<string,FieldDefinition[]>)[(props.study.templateCode||'').toLowerCase()+'_'+(props.study.legacy_version||'1')]||[];return Object.entries(fields.value).filter(([key,value])=>!key.startsWith('_')&&key!=='description'&&value.value).map(([key,value])=>({key,label:definitions.find(f=>f.key===key)?.label||key,value:resolveValue(value)}))})
const pending=computed(()=>props.study.fields._calculation_pending?.value==='1')
</script>
<template><article class="document-sheet"><div class="document-header"><span class="document-brand"><UIcon name="i-lucide-activity"/>Протокол исследования</span><span>{{date(study.date)}} · № {{study.id}}</span></div><h2>{{study.title}}</h2><dl class="document-patient"><div><dt>Пациент</dt><dd>{{study.patientName||'Без карточки пациента'}}</dd></div><div><dt>Дата рождения</dt><dd>{{date(study.patientBirthdate)}}</dd></div><div><dt>Врач</dt><dd>{{study.doctor||'Не указан'}}</dd></div></dl><p v-if="study.status==='draft'||study.status==='legacy:0'" class="print-unit-note">ЧЕРНОВИК. Исследование не завершено.</p><p v-if="study.status==='deleted'" class="print-unit-note">ДОКУМЕНТ УДАЛЁН. Архивный просмотр.</p><p v-if="study.status==='legacy:2'" class="print-unit-note">Запись была удалена в исходной программе. Документ предоставлен для архивного просмотра.</p><p v-if="pending" class="print-unit-note">Вычисленные значения удалены после изменения размеров. Расчёт не выполнен.</p><p v-if="study.templateCode?.toLowerCase()==='shit'" class="print-unit-note">В исходном шаблоне объём обозначен как «мм». Обозначения сохранены для сопоставления с архивом. При размерах в миллиметрах исходная формула рассчитывает объём в см³.</p><section class="document-section"><div v-if="rendered.supported&&!rendered.unknownValues.length" class="legacy-protocol" v-html="rendered.html"></div><template v-else><p class="mb-4 text-slate-600">Показаны сохранённые параметры. Точный шаблон не определён или требует проверки.</p><dl class="archive-fields"><div v-for="p in parameters" :key="p.key"><dt>{{p.label}}</dt><dd>{{p.value}}</dd></div></dl></template><p v-if="study.fields.description?.value" class="preserve-lines mt-5">{{study.fields.description.value}}</p></section><section class="document-section"><h3>Заключение</h3><p class="preserve-lines">{{study.conclusion||'Не заполнено'}}</p></section><section v-if="study.addition" class="document-section"><h3>Дополнение и рекомендации</h3><p class="preserve-lines">{{study.addition}}</p></section><footer class="document-signature"><span>Врач: {{study.doctor||'________________'}}</span><span>Подпись __________________</span></footer></article></template>
